 81	function createStackHarness(stubs = {}) {
 82	  const stateDir = mkdtempSync(
 83	    join(tmpdir(), 'detran-stack-persistent-state-'),
 84	  );
 85	  const bin = mkdtempSync(join(tmpdir(), 'detran-stack-persistent-stubs-'));
 86	  const callsPath = join(stateDir, 'stub-calls.log');
 87	  const backendEnvironment = join(stateDir, 'backend-environment.log');
 88	  const startedPids = join(stateDir, 'started-pids.log');
 89	  writeFileSync(callsPath, '');
 90	  writeFileSync(startedPids, '');
 91	  const defaults = {
 92	    docker: `case "${'${1:-}'}" in
 93	  info) exit 0 ;;
 94	  inspect)
 95	    [[ "$*" == *--format* ]] && { printf '%s\\n' true; exit 0; }
 96	    exit 0
 97	    ;;
 98	  exec) exit 0 ;;
 99	  volume) exit 0 ;;
100	  compose)
101	    if [[ "$*" == *'version --short'* ]]; then
102	      printf '%s\\n' "${'${DETRAN_TEST_COMPOSE_VERSION:-2.24.4}'}"
103	    fi
104	    exit 0
105	    ;;
106	esac
107	exit 0`,
108	    pnpm: `if [[ "$*" == *'--filter @detran/app start'* ]]; then
109	  env | LC_ALL=C sort > "${backendEnvironment}"
110	fi
111	if [[ "$*" == *'--filter @detran/app start'* || "$*" == *'exec ng serve'* ]]; then
112	  printf '%s\\n' "$$" >> "${startedPids}"
113	  trap 'exit 0' TERM INT
114	  while :; do read -r -t 60 || :; done
115	fi
116	exit 0`,
117	    psql: 'exit 0',
118	    curl: 'exit 0',
119	    tail: 'exit 0',
120	    sleep: 'exit 0',
121	  };
122	  for (const [name, body] of Object.entries({ ...defaults, ...stubs })) {
123	    makeStub(bin, name, body);
124	  }
125	
126	  function invoke(args, env = {}) {
127	    const { PATH: requestedPath, ...restEnv } = env;
128	    const result = spawnSync('bash', [stackScript, ...args], {
129	      cwd: root,
130	      encoding: 'utf8',
131	      env: {
132	        DETRAN_STACK_STATE_DIR: stateDir,
133	        DETRAN_TEST_STUB_CALLS: callsPath,
134	        HOME: process.env.HOME ?? '/tmp',
135	        PATH: `${bin}:${requestedPath ?? ''}:${process.env.PATH ?? ''}`,
136	        ...restEnv,
137	      },
138	    });
139	    return { ...result, calls: readFileSync(callsPath, 'utf8') };
140	  }
141	
142	  function dispose() {
143	    for (const pid of readFileSync(startedPids, 'utf8')
144	      .split('\n')
145	      .filter(Boolean)) {
146	      try {
147	        process.kill(Number(pid), 'SIGTERM');
148	      } catch {
149	        // The process may already have been cleaned up by the stack.
150	      }
151	    }
152	    rmSync(stateDir, { recursive: true, force: true });
153	    rmSync(bin, { recursive: true, force: true });
154	  }
155	
156	  return { backendEnvironment, callsPath, dispose, invoke, startedPids };
157	}
