159	function assertRecordedProcessesStopped(path) {
160	  const pids = readFileSync(path, 'utf8')
161	    .split('\n')
162	    .filter(Boolean)
163	    .map(Number);
164	  assert.ok(pids.length > 0, 'the controlled start created local processes');
165	  for (const pid of pids) {
166	    let running = true;
167	    try {
168	      process.kill(pid, 0);
169	    } catch {
170	      running = false;
171	    }
172	    assert.equal(running, false, `process ${pid} was left running`);
173	  }
174	}
